// 同一World引用借完整原账；不创建第二Common保存点或把临时NPC返回当玩家提交。
#include "private_shop_command_results_integration.hpp"
#include "world_bundle.hpp"
#include "resident/domains/commerce/command_results/private_shop_command_results_codec.hpp"
#include "resident/domains/commerce/command_results/private_shop_command_result_player.hpp"
namespace hanmo::resident {namespace {
// 与ResidentWorld原preview/submit的唯一Actor门同一目录条件；不改旧NPC采纳或人物资格。
PrivateShopSubmissionAuthority submission_authority(const WorldBundle& w){return w.dynamic_enabled()&&w.catalog->director&&w.catalog->director->dynamic_subjects?PrivateShopSubmissionAuthority::controlled_player:PrivateShopSubmissionAuthority::legacy_actor_api;}
Status layout(const WorldBundle& w){const auto enabled=w.private_shop_command_results_enabled();auto pair=validate_private_shop_command_results_pair(enabled,w.private_shops_enabled(),w.catalog->identity.module_versions);if(!pair.ok)return pair;if(enabled!=w.private_shop_command_results_seed_complete)return common_failure("PrivateShopCommandResultsSeedRequired");if(!enabled&&(w.private_shop_command_results.version!=1||(!w.private_shop_command_results.bindings.empty()||!w.private_shop_command_results.control_bindings.empty())))return common_failure("UnexpectedPrivateShopCommandResultsState");if(enabled&&(!w.private_shops_seed_complete||w.catalog->private_shop_command_results->version!=1))return common_failure("PrivateShopCommandResultsPairRequired");return common_success();}
}
Status initialize_private_shop_command_results_world_in_candidate(WorldBundle& w){if(!w.private_shop_command_results_enabled())return layout(w);if(w.common.tick()!=0||!w.private_shops_enabled()||!w.private_shops_seed_complete||w.private_shop_command_results_seed_complete||w.private_shop_command_results.version!=1||(!w.private_shop_command_results.bindings.empty()||!w.private_shop_command_results.control_bindings.empty()))return common_failure("PrivateShopCommandResultsInitialBoundaryRequired");auto valid=validate_private_shop_command_results(w.common,w.private_shops,&w.private_shop_command_results,&w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr);if(!valid.ok)return valid;w.private_shop_command_results_seed_complete=true;return layout(w);}
Status validate_private_shop_command_results_world(const WorldBundle& w,ProjectionWriter* projection){auto valid=layout(w);return valid.ok?validate_private_shop_command_results(w.common,w.private_shops,w.private_shop_command_results_enabled()?&w.private_shop_command_results:nullptr,&w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr,projection):valid;}
Status validate_private_shop_command_result_player_world(const WorldBundle& w,ProjectionWriter* projection){auto valid=layout(w);if(!valid.ok)return valid;valid=validate_private_shop_command_result_player_history(w.common,w.private_shops,w.private_shop_command_results_enabled()?&w.private_shop_command_results:nullptr,w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr,submission_authority(w),projection);if(!valid.ok||!w.private_shop_command_results_enabled())return valid;valid=validate_private_shop_command_related_sources(w.private_shops,&w.private_shop_command_results,w.tasks.shop_orders?&*w.tasks.shop_orders:nullptr,w.private_shop_liquidations_enabled()?&w.private_shop_liquidations:nullptr);if(!valid.ok)return valid;
 return validate_private_shop_command_control_anchors(&w.private_shop_command_results,w.family_legacy,w.family_disciple_legacy_enabled()?&w.family_disciple_legacy:nullptr,w.family_biological_legacy_enabled()?&w.family_biological_legacy:nullptr);}

Status bind_private_shop_command_results_world(const WorldBundle* before,WorldBundle& w,const StableId& actor,Integer sequence,const CommitResult& result){auto valid=layout(w);if(!valid.ok)return valid;if(!w.private_shop_command_results_enabled()){if(before&&before->private_shop_command_results_enabled())return common_failure("PrivateShopCommandResultsCandidateMismatch");return common_success();}if(!before||before==&w||before->catalog.get()!=w.catalog.get()||!before->private_shop_command_results_enabled())return common_failure("PrivateShopCommandResultsBeforeWorldRequired");valid=layout(*before);if(!valid.ok)return valid;return bind_private_shop_command_results_in_candidate(before->common,before->private_shops,before->private_shop_command_results,w.common,w.private_shops,w.private_shop_command_results,actor,sequence,result,&before->family,before->family_legacy_enabled()?&before->family_legacy:nullptr,&w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr,submission_authority(*before));}
}
